+// The audit trail: one entry per request that changes data, kept in
+// `store.data.audit` (oldest first). Entries are never edited or deleted.
+
+/** Finds the API key record for a key string, or null. */
+export function findApiKey(store, key) {
+  return (store.data.apiKeys ?? []).find((k) => k.key === key) ?? null;
+}
+
+/** Appends an audit entry (time is an ISO instant given by the caller). */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
