+// Request authorization: Bearer keys with the roles viewer, cook, manager.
+import { AppError } from "../errors.js";
+import { findApiKey } from "../domain/audit.js";
+
+// What a cook may do besides reading: cook, waste, temperatures, stock-take counts.
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** Whether `role` may call `method` on `path`. */
+export function allowed(role, method, path) {
+  if (role === "manager") return true;
+  if (path === "/audit") return false;
+  if (method === "GET") return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_WRITES.some(([m, re]) => m === method && re.test(path));
+}
+
+/** Returns the key record for the request's Bearer key; throws unauthorized. */
+export function authenticate(store, headers) {
+  const h = Object.entries(headers).find(([k]) => k.toLowerCase() === "authorization")?.[1];
+  const m = /^Bearer (.+)$/.exec(typeof h === "string" ? h : "");
+  const record = m ? findApiKey(store, m[1]) : null;
+  if (!record) throw new AppError("unauthorized");
+  return record;
+}
+
+/** Throws forbidden unless the key's role may call `method` on `path`. */
+export function authorize(record, method, path) {
+  if (!allowed(record.role, method, path)) throw new AppError("forbidden");
+}
